export function courseModuleFor(subject: SubjectId, title?: string | null) {
  const subjectModules = COURSE_MODULES.filter((module) => module.subject === subject);
  if (!title) return subjectModules[0];
  return subjectModules.find((module) => module.title === title || module.titleEn === title || module.id === title) || subjectModules[0];
}

export function sourcesForCourseModule(module: CourseModule) {
  return module.sourceIds
    .map((id) => COURSE_SOURCES.find((source) => source.id === id))
    .filter((source): source is CourseSource => Boolean(source));
}

export function buildCourseModuleDsl(module: CourseModule, mode: TeachingMode, locale: "zh" | "en") {
  const stage = STAGE_COPY[module.level];
  const primaryOverview = locale === "en" ? module.overviewEn : module.overview;
  const secondaryOverview = locale === "en" ? module.overview : module.overviewEn;
  const primaryInquiry = locale === "en" ? module.inquiryEn : module.inquiry;
  const secondaryInquiry = locale === "en" ? module.inquiry : module.inquiryEn;

  const modeSection = mode === "case"
    ? locale === "en"
      ? `## Worked case\n${primaryInquiry}\n\nAnalyze the case in four passes: identify the decision or claim; list constraints and missing evidence; construct the strongest competing explanation; state what observation would change your judgment.\n\n## 案例分析\n${secondaryInquiry}\n\n依次识别判断、约束与缺失证据，提出最强竞争性解释，再说明什么观察会改变你的结论。`
      : `## 案例分析\n${primaryInquiry}\n\n依次识别判断、约束与缺失证据，提出最强竞争性解释，再说明什么观察会改变你的结论。\n\n## Worked case\n${secondaryInquiry}\n\nIdentify the decision or claim, list constraints and missing evidence, construct the strongest rival explanation, and state what observation would change your judgment.`
    : mode === "close-reading"
      ? locale === "en"
        ? `## Source-reading protocol\nOpen one of the linked course sources and read a short section in four passes: vocabulary, claim structure, evidence, and limits. Record one sentence you accept, one you question, and the evidence needed to decide.\n\n## 原典精读协议\n打开下方开放来源，依次检查术语、论证结构、证据和边界。记录一句你接受的判断、一句你质疑的判断，以及作出决定还需要的证据。`
        : `## 原典精读协议\n打开下方开放来源，依次检查术语、论证结构、证据和边界。记录一句你接受的判断、一句你质疑的判断，以及作出决定还需要的证据。\n\n## Source-reading protocol\nRead a short section from a linked open source in four passes: vocabulary, claim structure, evidence, and limits. Record one claim you accept, one you question, and the evidence needed to decide.`
      : locale === "en"
        ? `## Guided inquiry\n${primaryInquiry}\n\nBefore answering, define the key term, give one counterexample, and state the boundary conditions of your conclusion.\n\n## 引导练习\n${secondaryInquiry}\n\n回答前先定义核心术语，给出一个反例，并说明结论的适用条件。`
        : `## 引导练习\n${primaryInquiry}\n\n回答前先定义核心术语，给出一个反例，并说明结论的适用条件。\n\n## Guided inquiry\n${secondaryInquiry}\n\nBefore answering, define the key term, give one counterexample, and state the boundary conditions of your conclusion.`;

  return `${locale === "en" ? "## Core explanation" : "## 核心解释"}\n{{${module.title}|CN}} · {{${module.titleEn}|EN}}\n\n${primaryOverview}\n\n${locale === "en" ? "## 中文理解" : "## English explanation"}\n${secondaryOverview}\n\n${locale === "en" ? "## Learning stage" : "## 学习阶段"}\n${locale === "en" ? stage.en : stage.zh}\n\n${modeSection}\n\n## ${locale === "en" ? "Multilingual concept map" : "多语概念地图"}\n${SUBJECT_TERMS[module.subject]}`;
}
